import {createRunner,displayValue} from './runner.mjs?v=7';
import {escapeHTML as e} from './engine.mjs?v=7';
const examples={
 'Add two numbers':{hint:'Enter 4 and 6 when prompted. The output should be 10.',code:'BEGIN\n  DECLARE first AS REAL\n  DECLARE second AS REAL\n  DECLARE total AS REAL\n  INPUT first\n  INPUT second\n  SET total = first + second\n  OUTPUT total\nEND'},
 'IF ELSE decision':{hint:'Try 49, then restart and try 50 to compare the decision paths.',code:'BEGIN\n  DECLARE mark AS REAL\n  INPUT mark\n  IF mark >= 50 THEN\n    OUTPUT "Pass"\n  ELSE\n    OUTPUT "Revise"\n  ENDIF\nEND'},
 'FOR and a running total':{hint:'Enter 2, 3 and 4 as the loop requests each value. The total should be 9.',code:'BEGIN\n  DECLARE i AS INTEGER\n  DECLARE value AS REAL\n  DECLARE total AS REAL\n  SET total = 0\n  FOR i = 1 TO 3\n    INPUT value\n    SET total = total + value\n  ENDFOR\n  OUTPUT total\nEND'},
 'WHILE countdown':{hint:'Enter 3 to see three loop iterations. Enter 0 after restarting to see the body skipped.',code:'BEGIN\n  DECLARE number AS INTEGER\n  INPUT number\n  WHILE number > 0 DO\n    OUTPUT number\n    SET number = number - 1\n  ENDWHILE\nEND'},
 'Sentinel average':{hint:'Enter 10, 20 and -1. The result should be 15. A first input of -1 displays No data.',code:'BEGIN\n  DECLARE value AS REAL\n  DECLARE total AS REAL\n  DECLARE count AS INTEGER\n  SET total = 0\n  SET count = 0\n  INPUT value\n  WHILE value <> -1 DO\n    SET total = total + value\n    SET count = count + 1\n    INPUT value\n  ENDWHILE\n  IF count > 0 THEN\n    OUTPUT total / count\n  ELSE\n    OUTPUT "No data"\n  ENDIF\nEND'},
 'REPEAT input validation':{hint:'Enter 101, then -5, then 70. UNTIL becomes TRUE only for a valid mark.',code:'BEGIN\n  DECLARE mark AS REAL\n  REPEAT\n    INPUT mark\n  UNTIL mark >= 0 AND mark <= 100\n  OUTPUT mark\nEND'},
 'SWITCH menu':{hint:'Enter 1, 2 or an unsupported option to explore the selected branch.',code:'BEGIN\n  DECLARE option AS INTEGER\n  INPUT option\n  SWITCH option\n    CASE 1:\n      OUTPUT "Add"\n    CASE 2:\n      OUTPUT "View"\n    DEFAULT:\n      OUTPUT "Invalid option"\n  ENDSWITCH\nEND'},
 'Boolean approval':{hint:'Enter an age, then TRUE or FALSE for approval. The condition requires age at least 16 and approval.',code:'BEGIN\n  DECLARE age AS INTEGER\n  DECLARE approved AS BOOLEAN\n  INPUT age\n  INPUT approved\n  IF age >= 16 AND approved THEN\n    OUTPUT "Eligible"\n  ELSE\n    OUTPUT "Requirements not met"\n  ENDIF\nEND'}
};
const session={code:examples['Add two numbers'].code,preset:'Add two numbers',runner:null,history:[],position:0,waiting:null,waitingVisible:false,input:'',editorOpen:true,message:''};
export function interactiveTracePage({view,crumb,sidebar,initialCode=null,openDiagram}){
 const $=selector=>view.querySelector(selector);
 if(initialCode!==null){session.code=initialCode;session.runner=null;session.history=[];session.position=0;session.waiting=null;session.waitingVisible=false;session.input='';session.editorOpen=true;session.message='Code copied from the diagram lab. Prepare it to check the supported tracing syntax.';}
 view.innerHTML=crumb('Interactive tracing')+`<p class="eyebrow">YOUR CODE. EVERY STEP EXPLAINED.</p><h1>Follow your logic as it runs.</h1><p class="lede">Write a scalar program, supply its inputs and inspect each change. The tracer highlights the statement it just executed, or the INPUT statement waiting for you.</p><div class="button-row"><a class="button secondary" href="#trace-guided">Guided array and sorting traces</a></div><details id="runner-editor" class="panel runner-editor" ${session.editorOpen?'open':''}><summary>Edit or choose your pseudocode</summary><div class="runner-editor-head"><label class="field-label">Load an example<select id="runner-example">${Object.keys(examples).map(name=>`<option ${session.preset===name?'selected':''}>${e(name)}</option>`).join('')}</select></label><p id="runner-example-hint">${e(examples[session.preset].hint)}</p></div><label class="field-label" for="runner-code">Your pseudocode</label><textarea id="runner-code" class="editor" spellcheck="false" maxlength="20000">${e(session.code)}</textarea><div class="button-row"><button id="runner-prepare" class="button">Prepare my code</button><button id="runner-clean" class="button secondary">Remove pasted line numbers</button><button id="runner-diagram" class="button ghost">View as a flowchart</button></div><p>Declare each variable before using it. Editing the code clears its current trace.</p></details><p class="status" role="status" id="runner-message">${e(session.message)}</p><div id="runner-workbench"></div><details class="panel syntax runner-guide"><summary>What this first interactive tracer supports</summary><p>Use one statement per line. Names are case-insensitive. Declare INTEGER, REAL, STRING or BOOLEAN scalar variables. Use SET (or plain assignments), INPUT, OUTPUT, IF/ELSE/ELSEIF, FOR, WHILE, REPEAT/UNTIL and SWITCH/CASE. Constants may use CONSTANT name AS type = expression.</p><p>Expressions support parentheses, +, -, *, /, DIV, MOD, comparisons, AND, OR and NOT. AND and OR short-circuit. Arithmetic and comparisons bind before NOT, then AND, then OR. + adds numbers or joins two strings. Type mixing is rejected. DIV truncates towards zero; MOD uses that quotient. FOR bounds are inclusive and fixed on loop entry. STEP may be a nonzero integer.</p><p>INPUT asks for one value at a time. Enter TRUE/FALSE for BOOLEAN and text without quotation marks for STRING. In code, string literals need quotes. Declarations start unassigned unless you give an initial value. Previous replays recorded states; restart to try different inputs.</p><p>Arrays, methods, function calls, RETURN, classes and objects are not executed in this version. Their diagram and guided learning tools remain available. The tracer stops after 2,000 steps, 50 variables, 200 output records or 10,000 output characters. Source limits are 20,000 characters and 300 non-empty lines. Text values are limited to 2,000 characters. REAL arithmetic uses browser floating-point numbers.</p><p>Everything runs locally in this browser. Code, inputs and trace history stay in page memory and disappear on refresh. No AI API, student account or shared execution database is used.</p></details>`;
 sidebar();
 $('#runner-editor').ontoggle=event=>{session.editorOpen=event.currentTarget.open;};
 function message(text){session.message=text;$('#runner-message').textContent=text;}
 function invalidate(note='Code changed. Prepare it again before stepping.'){session.runner=null;session.history=[];session.position=0;session.waiting=null;session.waitingVisible=false;session.input='';message(note);render();}
 function prepare(){try{session.code=$('#runner-code').value;session.runner=createRunner(session.code);session.history=[session.runner.initial()];session.position=0;session.waiting=null;session.waitingVisible=false;session.input='';message('Prepared. Choose Next step to begin.');$('#runner-editor').open=false;render();}catch(err){invalidate(err.message);$('#runner-editor').open=true;}}
 function advance(raw){if(!session.runner)return;if(session.position<session.history.length-1){session.position++;session.waitingVisible=false;render();return;}
  try{const state=session.runner.step(raw);if(state.kind==='input'){session.waiting=state;session.waitingVisible=true;message(state.note);}else{session.waiting=null;session.waitingVisible=false;session.input='';session.history.push(state);session.position=session.history.length-1;message(state.note);}render();if(session.waitingVisible)$('#runner-input')?.focus();}
  catch(err){if(err.recoverable){message(err.message);$('#runner-input-error').textContent=err.message;return;}const previous=session.history.at(-1);session.history.push({...previous,kind:'error',line:err.line||previous?.line,condition:null,changed:[],note:err.message});session.position=session.history.length-1;session.waiting=null;session.waitingVisible=false;message(err.message+' Edit and prepare again, or restart.');render();}
 }
 function render(){const host=$('#runner-workbench');if(!session.history.length){host.innerHTML='<div class="panel runner-empty"><h2>Ready to explore?</h2><p>Choose an example or write your program above, then select Prepare my code.</p><p>You will see its active line, declared variables, decisions and output here.</p></div>';return;}
  const stored=session.history[session.position],atTip=session.position===session.history.length-1,state=atTip&&session.waitingVisible?session.waiting:stored,waiting=state.kind==='input';
  const changed=new Set((state.changed||[]).map(n=>n.toLowerCase()));
  const value=v=>v.type==='STRING'&&v.value!==undefined?JSON.stringify(v.value):displayValue(v.value);
  host.innerHTML=`<div class="runner-controls"><div class="button-row"><button class="button secondary" id="runner-prev" ${session.position===0&&!waiting?'disabled':''}>Previous step</button><button class="button" id="runner-next" ${waiting||(atTip&&['done','error'].includes(state.kind))?'disabled':''}>${atTip?'Next step':'Next recorded step'}</button><button class="button secondary" id="runner-restart">Restart with new inputs</button><button class="button ghost" id="runner-edit">Edit code</button></div><p class="runner-state-label" role="status">${state.kind==='ready'?'Ready':waiting?'Waiting for input':state.kind==='done'?'Completed':state.kind==='error'?'Stopped with an error':'Step '+state.steps}${state.line?' - line '+state.line:''}${state.condition===true?' - condition TRUE':state.condition===false?' - condition FALSE':''}</p></div><div class="runner-layout"><section class="panel"><h2>Your running program</h2><p class="runner-small">The highlighted line is the last executed statement or the pending INPUT.</p><pre class="runner-source"><code>${session.code.split('\n').map((line,i)=>`<span class="line-code ${state.line===i+1?'trace-current':''}" ${state.line===i+1?'aria-current="step"':''}><span class="ln">${i+1}</span>${e(line)}</span>`).join('')}</code></pre></section><section class="panel"><h2>Current state</h2><p class="runner-explanation ${state.kind==='error'?'runner-error':''}" role="status">${e(state.note)}</p>${waiting?`<form id="runner-input-form" class="runner-input-form"><label class="field-label" for="runner-input">Input for ${e(state.name)} (${e(state.type)})</label><input id="runner-input" type="text" autocomplete="off" maxlength="2000" value="${e(session.input)}" aria-describedby="runner-input-help runner-input-error"><p id="runner-input-help">${state.type==='BOOLEAN'?'Enter TRUE or FALSE.':state.type==='STRING'?'Enter text without quotation marks.':state.type==='INTEGER'?'Enter a whole number.':'Enter a number, using a decimal point if needed.'}</p><button class="button" type="submit">Use this input</button><p id="runner-input-error" class="runner-error" role="status"></p></form>`:''}<h3>Variables</h3><div class="scroll-table"><table class="runner-variables"><thead><tr><th>Name</th><th>Type</th><th>Value</th></tr></thead><tbody>${state.variables.length?state.variables.map(v=>`<tr class="${changed.has(v.name.toLowerCase())?'runner-changed':''}"><th scope="row">${e(v.name)}${v.constant?' <small>(constant)</small>':''}</th><td>${e(v.type)}</td><td><code>${e(value(v))}</code></td></tr>`).join(''):'<tr><td colspan="3">No declarations executed yet.</td></tr>'}</tbody></table></div><p class="runner-small">Highlighted rows were declared or changed in this step.</p><h3>Output</h3><pre class="runner-output">${e(state.output.length?state.output.join('\n'):'No output yet')}</pre></section></div><details class="panel runner-history"><summary>Recorded trace history (${session.history.length-1} events)</summary><p>Previous and Next replay these states without running them again. Only the most recent 40 rows up to this position are shown.</p><div class="scroll-table"><table><thead><tr><th>Step</th><th>Line</th><th>What happened</th></tr></thead><tbody>${session.history.slice(Math.max(1,session.position-39),session.position+1).map(s=>`<tr><td>${s.steps}</td><td>${s.line??'-'}</td><td>${e(s.note)}</td></tr>`).join('')}</tbody></table></div></details>`;
  $('#runner-prev').onclick=()=>{if(waiting){session.waitingVisible=false;}else if(session.position>0)session.position--;message('Reviewing a recorded state. Restart to change inputs.');render();};$('#runner-next').onclick=()=>advance();$('#runner-restart').onclick=prepare;$('#runner-edit').onclick=()=>{$('#runner-editor').open=true;$('#runner-code').focus();};
  if(waiting){$('#runner-input').oninput=event=>{session.input=event.target.value;};$('#runner-input-form').onsubmit=event=>{event.preventDefault();session.input=$('#runner-input').value;advance(session.input);};}
 }
 $('#runner-code').oninput=event=>{session.code=event.target.value;invalidate();};$('#runner-example').onchange=event=>{session.preset=event.target.value;session.code=examples[session.preset].code;$('#runner-code').value=session.code;$('#runner-example-hint').textContent=examples[session.preset].hint;invalidate('Example loaded. Prepare it to begin.');};$('#runner-prepare').onclick=prepare;$('#runner-clean').onclick=()=>{const cleaned=$('#runner-code').value.replace(/^\s*\d{1,3}[.)]?\s+(?=[A-Za-z_/])/gm,'');if(cleaned===$('#runner-code').value){message('No leading line-number labels were found.');return;}session.code=cleaned;$('#runner-code').value=cleaned;invalidate('Line-number labels removed. Review the code, then prepare it.');};$('#runner-diagram').onclick=()=>openDiagram($('#runner-code').value);render();
}
